		const path = resolve(directory, entry.name);
		if(entry.isDirectory()) paths.push(...await visit(path));
		else if(entry.isFile() && entry.name.endsWith(".test.mjs")) paths.push(relative(root, path).replaceAll("\\", "/"));
	}
	return paths;
};

